<template><view class="page"><view class="custom-nav" :style="{ paddingTop: statusBarHeight + 'px' }"><view class="nav-row"><text class="nav-icon" @click="goBack">←</text><text class="nav-title">阅读测速</text><text class="nav-icon empty"> </text></view></view><view class="content"><view class="rs-text" v-if="!finished">{{ text }}</view><view class="rs-result" v-else><text class="rs-wpm">{{ wpm }}</text><text class="rs-label">字/分钟</text><text class="rs-time">用时 {{ elapsed }}秒</text></view><view class="rs-btn" @click="startRead" v-if="!reading && !finished"><text>开始阅读</text></view><view class="rs-btn finish" @click="finishRead" v-if="reading"><text>读完了</text></view><view class="rs-btn" @click="reset" v-if="finished"><text>再来</text></view></view></view></template><script setup>import { ref, onMounted } from "vue"
const statusBarHeight = uni.getSystemInfoSync().statusBarHeight || 20
const text = "Technology is rapidly changing our world. Every day brings new innovations that shape how we live work and communicate."
const reading = ref(false); const finished = ref(false); const wpm = ref(0); const elapsed = ref(0)
var startTime = null
function startRead() { reading.value = true; startTime = Date.now() }
function finishRead() { reading.value = false; finished.value = true; elapsed.value = Math.floor((Date.now() - startTime) / 1000); wpm.value = Math.round(80 / (elapsed.value / 60)) }
function reset() { reading.value = false; finished.value = false; wpm.value = 0; elapsed.value = 0 }
function goBack() { uni.navigateBack() }
onMounted(function() { if (!uni.getStorageSync("isLoggedIn")) { uni.reLaunch({ url: "/pages/login/login" }); return } })
</script><style scoped>.page{min-height:100vh;background:#f5f7fb}.custom-nav{background:linear-gradient(135deg,#00b894,#55efc4);width:100%}.nav-row{height:88rpx;display:flex;align-items:center;padding:0 24rpx}.nav-icon{width:72rpx;text-align:center;font-size:48rpx;color:#fff;font-weight:700;flex-shrink:0}.nav-icon.empty{visibility:hidden}.nav-title{flex:1;text-align:center;font-size:32rpx;color:#fff;font-weight:600}.content{padding:32rpx}.rs-text{background:#fff;border-radius:20rpx;padding:32rpx;font-size:30rpx;line-height:2;color:#333;margin-bottom:32rpx}.rs-result{text-align:center;background:#fff;border-radius:20rpx;padding:48rpx;margin-bottom:32rpx}.rs-wpm{font-size:80rpx;font-weight:700;color:#00b894;display:block}.rs-label{font-size:24rpx;color:#999;display:block}.rs-time{font-size:26rpx;color:#666;display:block;margin-top:8rpx}.rs-btn{background:linear-gradient(135deg,#00b894,#55efc4);border-radius:16rpx;padding:28rpx;text-align:center}.rs-btn text{font-size:32rpx;color:#fff;font-weight:600}.rs-btn.finish{background:linear-gradient(135deg,#e17055,#d63031)}</style>